cat > /tmp/cmp.py <<'EOF'
import redis
bad=0; n=0
for db in range(16):
    a=redis.Redis(port=6379,db=db); b=redis.Redis(port=6380,db=db)
    ka=set(a.scan_iter(count=1000)); kb=set(b.scan_iter(count=1000))
    if ka!=kb: print("db",db,"keyset diff",len(ka-kb),len(kb-ka)); bad+=1
    for k in ka & kb:
        n+=1
        t=a.type(k)
        if t!=b.type(k): print("type",db,k); bad+=1; continue
        ta,tb=a.pttl(k),b.pttl(k)
        if (ta<0)!=(tb<0) or abs(ta-tb)>2000: print("ttl",db,k,ta,tb); bad+=1
        t=t.decode()
        if t=="string": va,vb=a.get(k),b.get(k)
        elif t=="hash": va,vb=a.hgetall(k),b.hgetall(k)
        elif t=="list": va,vb=a.lrange(k,0,-1),b.lrange(k,0,-1)
        elif t=="set": va,vb=a.smembers(k),b.smembers(k)
        elif t=="zset": va,vb=a.zrange(k,0,-1,withscores=True),b.zrange(k,0,-1,withscores=True)
        elif t=="stream":
            va=(a.xrange(k),a.xinfo_groups(k),[ (a.xinfo_consumers(k,g['name']), a.xpending_range(k,g['name'],'-','+',100000)) for g in a.xinfo_groups(k)], a.xinfo_stream(k)['last-generated-id'])
            vb=(b.xrange(k),b.xinfo_groups(k),[ (b.xinfo_consumers(k,g['name']), b.xpending_range(k,g['name'],'-','+',100000)) for g in b.xinfo_groups(k)], b.xinfo_stream(k)['last-generated-id'])
            # idle times differ naturally; strip them
            def strip(v):
                import json
                return json.loads(json.dumps(v,default=lambda o:o.decode() if isinstance(o,bytes) else str(o)).replace('"','"'), object_hook=lambda d:{x:y for x,y in d.items() if x not in('idle','inactive','time_since_delivered','pending' if False else '__')})
            va,vb=strip(va),strip(vb)
        else: print("other type",t,k); va=vb=None
        if va!=vb: print("value",db,k,t); bad+=1
print("checked",n,"bad",bad)
EOF
python3 /tmp/cmp.py 2>&1 | tail -20
